#include "gtest/gtest.h"
#include "response_builder.h"

class ResponseBuilderTest : public ::testing::Test {
protected:
// function is generated by ai
  std::string SerializeResponse(const std::unique_ptr<response>& response_obj) {
    if (!response_obj) {
        return "";
    }
    std::string response_str;
    response_str.append("HTTP/1.1 " + response_obj->status_code + "\r\n");
    for(const auto& header : response_obj->headers) {
        response_str.append(header + "\r\n");
    }
    response_str.append("\r\n" + response_obj->body);
    return response_str;
  }

  void ValidateResponseFormat(const std::string& response,
                              const std::string& expected_status,
                              const std::string& expected_content_type,
                              const std::string& expected_body) {
    // Check status line
    EXPECT_TRUE(response.find("HTTP/1.1 " + expected_status) != std::string::npos);
    
    // Check content type header
    EXPECT_TRUE(response.find("Content-Type: " + expected_content_type) != std::string::npos);
    
    // Check content length header
    std::string content_length = "Content-Length: " + std::to_string(expected_body.size());
    EXPECT_TRUE(response.find(content_length) != std::string::npos);
    
    // Check connection header
    EXPECT_TRUE(response.find("Connection: close") != std::string::npos);
    
    // Check body is at the end
    EXPECT_TRUE(response.find("\r\n\r\n" + expected_body) != std::string::npos);
  }
};

// Test Ok response with default content type
TEST_F(ResponseBuilderTest, OkResponseDefault) {
  std::string body = "Success!";
  auto response_obj = ResponseBuilder::Ok(body);
  std::string response = SerializeResponse(response_obj);
  
  ValidateResponseFormat(response, "200 OK", "text/plain", body);
}

// Test Ok response with custom content type
TEST_F(ResponseBuilderTest, OkResponseCustomContentType) {
  std::string body = "<html><body>Hello</body></html>";
  auto response_obj = ResponseBuilder::Ok(body, "text/html");
  std::string response = SerializeResponse(response_obj);
  
  ValidateResponseFormat(response, "200 OK", "text/html", body);
}

