// Test response header order
TEST_F(ResponseBuilderTest, HeaderOrder) {
  auto response_obj = ResponseBuilder::Ok("test");
  std::string response = SerializeResponse(response_obj);
  
  size_t status_pos = response.find("HTTP/1.1");
  size_t content_type_pos = response.find("Content-Type:");
  size_t content_length_pos = response.find("Content-Length:");
  size_t connection_pos = response.find("Connection:");
  size_t body_pos = response.find("\r\n\r\n");
  
  // Verify header order
  EXPECT_LT(status_pos, content_type_pos);
  EXPECT_LT(content_type_pos, content_length_pos);
  EXPECT_LT(content_length_pos, connection_pos);
  EXPECT_LT(connection_pos, body_pos);
}

